define(["jquery"],function($){"use strict";var FIELD_IDS=["coursetext","datefrom","dateto","futureonly","includewaitlist"];var DEBOUNCE_DELAY=400;var init=function(formSelector){formSelector=formSelector||"form.f2f-filter-form";var $form=$(formSelector);if($form.length===0){return}setupAutoSubmit($form);setupUpcomingDatePrefill($form);setupResetButton($form)};var setupAutoSubmit=function($form){var timer=null;var submitDebounced=function(){if(timer){clearTimeout(timer)}timer=setTimeout(function(){$form.submit()},DEBOUNCE_DELAY)};FIELD_IDS.forEach(function(fieldId){var $field=$("#"+fieldId);if($field.length===0){return}if(fieldId==="coursetext"){$field.on("keydown",function(e){if(e.key==="Enter"){e.preventDefault();$form.submit()}})}else{$field.on("change",submitDebounced)}})};var setupUpcomingDatePrefill=function($form){var $upcomingCheckbox=$("#futureonly");var $startDateField=$("#datefrom");if($upcomingCheckbox.length===0||$startDateField.length===0){return}$upcomingCheckbox.on("change",function(){if($upcomingCheckbox.is(":checked")&&!$startDateField.val()){var today=new Date();var year=today.getFullYear();var month=String(today.getMonth()+1).padStart(2,"0");var day=String(today.getDate()).padStart(2,"0");var dateString=year+"-"+month+"-"+day;$startDateField.val(dateString)}})};var setupResetButton=function($form){var $resetBtn=$("#f2f-reset");if($resetBtn.length===0){return}$resetBtn.on("click",function(e){e.preventDefault();$("#coursetext").val("");$("#datefrom").val("");$("#dateto").val("");$("#futureonly").prop("checked",false);$("#includewaitlist").prop("checked",false);$form.submit()})};return{init:init}});
